import React, { Component } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import MyContext from '../contexts/MyContext';
import Menu from './MenuComponent';
import Category from './CategoryComponent';
import Product from './ProductComponent'; // <-- Nhúng file vừa tạo

// Khai báo tạm các trang khác
const Report = () => <h2 style={{ padding: '20px' }}>Trang Báo cáo</h2>;
const Order = () => <h2 style={{ padding: '20px' }}>Trang Đơn hàng</h2>;
const Customer = () => <h2 style={{ padding: '20px' }}>Trang Khách hàng</h2>;
const Voucher = () => <h2 style={{ padding: '20px' }}>Trang Mã giảm giá</h2>;

class Main extends Component {
  static contextType = MyContext;

  render() {
    if (this.context.token === '') return <div />;

    return (
      <div style={{ backgroundColor: '#F9F6F0', minHeight: '100vh', padding: '0 20px 20px' }}>
        <Menu />
        <Routes>
          <Route path="/admin" element={<Navigate replace to="/admin/category" />} />
          <Route path="/admin/report" element={<Report />} />
          <Route path="/admin/category" element={<Category />} />
          <Route path="/admin/product" element={<Product />} />
          <Route path="/admin/order" element={<Order />} />
          <Route path="/admin/customer" element={<Customer />} />
          <Route path="/admin/voucher" element={<Voucher />} />
        </Routes>
      </div>
    );
  }
}

export default Main;
